    "explanation": "The correct option is Liver. - Deamination is the process of removing the amino group (NH2) from amino acids, which are the building blocks of proteins. - The liver plays a crucial role in deamination, where amino acids are broken down, and the amino group is converted into ammonia (NH3) and then further processed into urea for excretion by the kidneys. Why other options are incorrect: Lungs: The lungs are primarily involved in gas exchange and do not play a significant role in deamination of proteins. Stomach: The stomach is involved in the initial stages of protein digestion but not in deamination. Kidney: The kidneys are responsible for filtering waste products and excess substances from the blood but do not directly carry out deamination. Heart: The heart is a muscular organ responsible for pumping blood and is not directly involved in the process of deamination. Hint: Think about which organ is responsible for processing amino acids and converting the amino groups into a form that can be excreted."
