    "topic": "All Questions",
    "difficulty": "Medium",
    "text": "After the following sentence, a list of possible interpretations of the sentence is given. Choose the interpretation that you consider most appropriate for each sentence. The members of staff told the principal that they took exception to his comments. This means that the members of staff",
