    "difficulty": "Medium",
    "text": "Whenever I told people that I was going to the Psychiatric Hospital, Yaba in Lagos, many of them looked at my face with some kind of suspicion or sympathy. At least that was the message that I read from their faces. I understood suspicion to mean that they might be troubled or worried if I had some psychiatric problem myself concerning the concept of sympathy, they might have thought that I had a patient that I went there to see or visit. How on earth they thought that way baffled me! In reality, the hospital was built for the care of people with some kind of psychiatric problem or another. Did it mean, then that all persons that one found in the hospital in any given time had psychiatric problems? Or, could someone not go to the place for things other than seeking psychiatric assistance? What might be responsible for this kind of attitude was the lack of education or precisely, good education. After all, education could help people differentiate their right from the left. people might have done was to request such to know what one was going there to do. Such a request would have solved the suspicion and sympathy problems. To read from someone's face as used in the passage means",
