    "explanation": "The verified answer is D. Here's how to solve this: Formula: The heat energy (Q) released or absorbed during a temperature change is calculated using: Q = mcΔT Where: M = mass of the object (in kilograms) C = specific heat capacity (in J/kg/K) ΔT = change in temperature (in Kelvin or Celsius, as the units cancel out) Convert Units: Mass: 50 g = 0.05 kg Temperature Change (ΔT): 85°C - 25°C = 60°C (which is equivalent to a 60K change) Calculate Heat (Q): Q = (0.05 kg) * (460 J/kg/K) * (60 K) = 1380 J = 1.38 x 10³ J Why other options are incorrect: A, B, C, E: These likely result from errors in calculations, forgetting to convert units, or misusing the formula."
