    "topic": "All Questions",
    "difficulty": "Medium",
    "text": "A clock is set at 8am. The clock gains 10min in 24hrs. What will be the true time when the clock indicates 1pm on the following day?",
    "options": [
      {
        "key": "A",
        "text": "48 minutes past 12"
      },
      {
        "key": "B",
        "text": "38 minutes past 12"
      },
      {
        "key": "C",
        "text": "28 minutes past 12"
      },
      {
        "key": "D",
        "text": "25 minutes past 12"
      }
    ],
    "correctAnswer": "C",
    "explanation": "28 minutes past 12 The clock gains 10 minutes in 24 hours, so it gains 10/24 = 5/12 minutes per hour. In 24 hours, it gains 5/12 × 24 = 10 minutes. In 12 hours, it gains 5 minutes. At 1 pm on the following day, it would show 1:05 pm, so the true time is 12:28."
