    "correctAnswer": "B",
    "explanation": "In the reaction CuO + H 2 → Cu + H 2 O, CuO is reduced to copper. Reduction is a chemical reaction in which a substance gains electrons. In this case, CuO gains electrons from H 2 to form Cu. Oxidation is the opposite of reduction. Oxidation is a chemical reaction in which a substance loses electrons. In this case, H 2 loses electrons to CuO to form H 2 O."
